"""Idempotent receipts binding a state to an audit record.

A receipt only names an ``id`` and the two 64-char lowercase hex digests of
the state and audit record it binds; the state and audit bytes themselves
are never read or written here.  Receipts are kept in an index stored as
UTF-8 compact JSON::

    {"items":[{"audit":...,"id":...,"state":...},...],"version":1}\\n

The top-level keys are fixed in the order ``items`` then ``version`` and
``version`` is always the integer 1.  ``items`` is an array of records
sorted ascending by ``id`` (ids are unique); each record carries the str
keys ``id``, ``state`` and ``audit`` and is canonically encoded with the
key order ``audit``, ``id``, ``state``.  Non-ASCII characters are preserved
unescaped and the file ends with exactly one ``\\n``.

A missing index file stands for an empty index; an existing file that
violates any byte, structure, order or field rule is corrupt.
"""

from __future__ import annotations

import json
import os
import re
from typing import Any

AUDIT = "audit"
ID = "id"
STATE = "state"

ITEMS = "items"
VERSION = "version"

_RECEIPT_KEYS = (ID, STATE, AUDIT)
_RECORD_KEYS = (AUDIT, ID, STATE)
_INDEX_KEYS = (ITEMS, VERSION)
_INDEX_VERSION = 1

_ID_RE = re.compile(r"[A-Za-z0-9._-]{1,64}\Z")
_DIGEST_RE = re.compile(r"[0-9a-f]{64}\Z")


class CorruptReceiptError(ValueError):
    """The receipt index exists but its bytes are not a valid index."""


def _is_digest(value: Any) -> bool:
    return isinstance(value, str) and _DIGEST_RE.fullmatch(value) is not None


def _validated_receipt(receipt: Any) -> dict[str, str]:
    """Validate one receipt and return a fresh dict in record key order."""
    if not isinstance(receipt, dict):
        raise TypeError("receipt must be a dict")
    if set(receipt.keys()) != set(_RECEIPT_KEYS):
        raise ValueError(
            "receipt must contain exactly the keys 'id', 'state' and 'audit'"
        )
    for key in _RECEIPT_KEYS:
        if not isinstance(receipt[key], str):
            raise TypeError(f"receipt {key} must be a str")
    receipt_id = receipt[ID]
    if _ID_RE.fullmatch(receipt_id) is None:
        raise ValueError("receipt id must match [A-Za-z0-9._-]{1,64}")
    if not _is_digest(receipt[STATE]):
        raise ValueError("receipt state must be 64 lowercase hex characters")
    if not _is_digest(receipt[AUDIT]):
        raise ValueError("receipt audit must be 64 lowercase hex characters")
    return {AUDIT: receipt[AUDIT], ID: receipt_id, STATE: receipt[STATE]}


def _serialize_index(records: list[dict[str, str]]) -> bytes:
    ordered = [
        {AUDIT: record[AUDIT], ID: record[ID], STATE: record[STATE]}
        for record in records
    ]
    index = {ITEMS: ordered, VERSION: _INDEX_VERSION}
    text = json.dumps(index, ensure_ascii=False, separators=(",", ":")) + "\n"
    return text.encode("utf-8")


def _parse_index(raw: bytes) -> list[dict[str, str]]:
    """Validate every byte of a receipt index and return its records.

    Raises :class:`CorruptReceiptError` for any UTF-8/JSON failure,
    non-canonical byte encoding, wrong key set or order, bad version,
    duplicate or unsorted ids, or a field that is not a well-formed str.
    """
    if raw == b"":
        raise CorruptReceiptError("receipt index is empty")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptReceiptError("receipt index is not valid UTF-8") from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise CorruptReceiptError("receipt index is not valid JSON") from exc

    if not isinstance(data, dict):
        raise CorruptReceiptError("receipt index must be a JSON object")
    if set(data.keys()) != set(_INDEX_KEYS):
        raise CorruptReceiptError(
            "receipt index must contain exactly the keys 'items' and 'version'"
        )
    if list(data.keys()) != list(_INDEX_KEYS):
        raise CorruptReceiptError(
            "receipt index keys must be in the order 'items', 'version'"
        )
    version = data[VERSION]
    # bool is a subclass of int; the version must be a genuine integer.
    if isinstance(version, bool) or not isinstance(version, int) or version != 1:
        raise CorruptReceiptError("receipt index version must be the integer 1")
    raw_items = data[ITEMS]
    if not isinstance(raw_items, list):
        raise CorruptReceiptError("receipt index items must be an array")

    records: list[dict[str, str]] = []
    for position, item in enumerate(raw_items):
        where = f"receipt index item {position}"
        if not isinstance(item, dict):
            raise CorruptReceiptError(f"{where} must be a JSON object")
        if set(item.keys()) != set(_RECORD_KEYS):
            raise CorruptReceiptError(
                f"{where} must contain exactly the keys 'audit', 'id' and 'state'"
            )
        if list(item.keys()) != list(_RECORD_KEYS):
            raise CorruptReceiptError(
                f"{where} keys must be in the order 'audit', 'id', 'state'"
            )
        audit_digest = item[AUDIT]
        record_id = item[ID]
        state_digest = item[STATE]
        if not isinstance(record_id, str) or _ID_RE.fullmatch(record_id) is None:
            raise CorruptReceiptError(f"{where} has an invalid id")
        if not _is_digest(state_digest):
            raise CorruptReceiptError(
                f"{where} state must be 64 lowercase hex characters"
            )
        if not _is_digest(audit_digest):
            raise CorruptReceiptError(
                f"{where} audit must be 64 lowercase hex characters"
            )
        records.append(
            {AUDIT: audit_digest, ID: record_id, STATE: state_digest}
        )

    ids = [record[ID] for record in records]
    if any(left >= right for left, right in zip(ids, ids[1:])):
        raise CorruptReceiptError(
            "receipt index ids must be unique and sorted ascending"
        )

    # Reject stray whitespace, non-canonical escapes, and any encoding that
    # is not the single compact form of the validated structure.
    if _serialize_index(records) != raw:
        raise CorruptReceiptError("receipt index is not canonically encoded")
    return records


def _read_index(path: str) -> list[dict[str, str]]:
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return []
    return _parse_index(raw)


def _atomic_write(path: str, payload: bytes) -> None:
    tmp_path = path + ".tmp"
    with open(tmp_path, "wb") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    try:
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise
    fd = os.open(os.path.dirname(os.path.abspath(path)), os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def put(path: str, receipt: dict[str, str]) -> dict[str, str]:
    """Bind ``receipt``'s state and audit digests under its id in the index.

    A new id is added and the index is atomically replaced.  Putting the
    same id with identical state and audit digests is idempotent: a fresh
    dict is returned without touching the file bytes.  The same id with
    different digests raises :class:`ValueError` and leaves the file
    unchanged.  The returned dict always has the key order
    ``audit``, ``id``, ``state``.

    Type violations raise :class:`TypeError`; a bad key set, id or digest
    format raises :class:`ValueError`; a corrupt index raises
    :class:`CorruptReceiptError`; other filesystem errors propagate as
    :class:`OSError`.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    record = _validated_receipt(receipt)

    records = _read_index(path)
    for existing in records:
        if existing[ID] == record[ID]:
            if (
                existing[STATE] != record[STATE]
                or existing[AUDIT] != record[AUDIT]
            ):
                raise ValueError(
                    f"receipt id {record[ID]!r} is already bound to a "
                    "different state or audit record"
                )
            # Idempotent replay: brand-new copy, no filesystem change.
            return dict(record)

    records.append(record)
    records.sort(key=lambda entry: entry[ID])
    _atomic_write(path, _serialize_index(records))
    return dict(record)


def get(path: str, id: str) -> dict[str, str] | None:
    """Return a fresh copy of the receipt stored under ``id``, or None.

    A missing index file or an index without that id yields ``None``.
    Type violations raise :class:`TypeError`; a malformed ``id`` raises
    :class:`ValueError`; a corrupt index raises
    :class:`CorruptReceiptError`; other filesystem errors propagate as
    :class:`OSError`.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    if not isinstance(id, str):
        raise TypeError("id must be a str")
    if _ID_RE.fullmatch(id) is None:
        raise ValueError("id must match [A-Za-z0-9._-]{1,64}")

    for record in _read_index(path):
        if record[ID] == id:
            return dict(record)
    return None

def verify_fork_aggregate_chain(
    root, successors, prune_policy, site_policy, policies, keyring, moment
):
    """Verify one fork aggregate supersession chain hop by hop, offline.

    ``root`` is the chain's cross-site fork decision aggregate packet
    and ``successors`` the ordered successor packets (possibly empty
    for a height-zero chain).  ``prune_policy`` is the invariant
    original ``{"batch", "sites", "threshold"}`` pruning policy,
    ``site_policy`` the invariant fork-proof site policy and
    ``policies`` the complete versioned decision site policy history --
    one entry per stage (the root policy plus one per successor), so
    its length is ``len(successors) + 1`` and the first carries
    ``policyVersion`` 1.  Only the root, the ordered successors, the two
    invariant policies, the policy history, the current keyring and the
    verification moment are consulted; no file is read or written and
    no input is modified.

    An empty successor list still verifies the root in full.  For a
    non-empty chain every hop is re-checked: the root, predecessor and
    height links, the append-only decision prefix, the old/new policy
    digests and single-step version rule, the non-decreasing effective
    moment, the invariant prune and fork-proof site policies, the
    per-new-decision re-authentication and the full stage re-tally, the
    verdict state machine and dual-policy sealer authorization, and the
    exact-issuer/version HMAC with a credential usable at both the
    hop's effective moment and the verification moment.

    On success returns a fresh mapping with the fixed keys
    ``rootDigest``, ``headDigest``, ``height`` (0 for a bare root),
    ``policyVersion`` (the head policy's version), ``status`` and
    ``commonDigest`` (the SHA-256 of the canonical common declaration
    when one is bound, otherwise null); repeated calls return equal but
    mutually independent results.  A non-bytes argument or a public
    field of the wrong type raises :class:`TypeError`; an empty value,
    an illegal version, a wrong policy count or a backwards moment
    raises :class:`ValueError`; a bad root raises
    :class:`InvalidAggregateForkDecisionAggregateError`; a bad
    successor or chain binding raises
    :class:`InvalidForkAggregateChainError`; a credential or signature
    fault raises :class:`AuthenticationError`.
    """
    if not isinstance(root, bytes):
        raise TypeError("root must be bytes")
    if not isinstance(successors, list):
        raise TypeError("successors must be a list")
    for index, successor in enumerate(successors):
        if not isinstance(successor, bytes):
            raise TypeError(f"successor {index} must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_policies = _pac_validated_policy_sequence(policies)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    if len(validated_policies) != len(successors) + 1:
        raise ValueError(
            "policies must provide one entry per chain stage (one more than "
            "the number of successors)"
        )
    if validated_policies[0][DS_POLICY_VERSION] != 1:
        raise ValueError("the root stage policy must carry policyVersion 1")

    return _verify_fac_chain(
        root, successors, validated_prune_policy, validated_site_policy,
        validated_policies, validated_keyring, verify_moment,
    )


# -- Offline batch verification and cross-chain fork detection -----------------

def _validated_fac_chain_batch(items: object) -> list[dict]:
    """Validate the fork aggregate chain batch before any chain runs.

    Each item holds exactly ``id`` (a non-empty str, unique across the
    batch), ``root`` (bytes), ``successors`` (a list of bytes, possibly
    empty) and ``policies`` (the complete versioned decision site
    policy history, one entry per stage).  Container, element and field
    type faults raise :class:`TypeError` (a :class:`bool` never poses
    as an int); an empty list, an empty or duplicate id, a wrong key
    set, an illegal policy, a wrong policy count or a root stage policy
    without ``policyVersion`` 1 raises :class:`ValueError`.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if not items:
        raise ValueError("items must be a non-empty list")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, item in enumerate(items):
        where = f"item {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if set(item.keys()) != _FAC_CHAIN_ITEM_KEYS:
            raise ValueError(
                f"{where} must contain exactly the keys 'id', 'policies', "
                "'root' and 'successors'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise ValueError(f"{where} id must be non-empty")
        if item_id in seen_ids:
            raise ValueError(f"duplicate id {item_id!r}")
        seen_ids.add(item_id)
        root = item[PAC_BATCH_ROOT]
        if not isinstance(root, bytes):
            raise TypeError(f"{where} root must be bytes")
        successors = item[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        for hop_index, successor in enumerate(successors):
            if not isinstance(successor, bytes):
                raise TypeError(f"{where} successor {hop_index} must be bytes")
        policies = item[PAC_BATCH_POLICIES]
        validated_policies = _pac_validated_policy_sequence(policies)
        if len(validated_policies) != len(successors) + 1:
            raise ValueError(
                f"{where} policies must provide one entry per chain stage "
                "(one more than the number of successors)"
            )
        if validated_policies[0][DS_POLICY_VERSION] != 1:
            raise ValueError(
                f"{where} root stage policy must carry policyVersion 1"
            )
        validated.append({
            ID: item_id,
            PAC_BATCH_ROOT: root,
            PAC_BATCH_SUCCESSORS: list(successors),
            PAC_BATCH_POLICIES: list(policies),
        })
    return validated


def _fac_chain_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One fork aggregate chain batch report with the fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_fac_chain_item(
    item: dict, prune_policy: object, site_policy: object,
    keyring: object, verify_moment: int
) -> dict:
    """Verify one batch chain in isolation and report its outcome.

    The root aggregate is verified on its own first, so a root fault is
    reported ``invalid-root`` while a successor or chain-binding fault
    is ``invalid-chain``; credential and signature faults are
    ``unauthenticated`` and a passing chain is ``verified``.
    """
    item_id = item[ID]
    root = item[PAC_BATCH_ROOT]
    successors = item[PAC_BATCH_SUCCESSORS]
    policies = item[PAC_BATCH_POLICIES]
    try:
        verify_fork_aggregate_chain(
            root, [], prune_policy, site_policy, policies[:1],
            keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateForkDecisionAggregateError, TypeError,
            ValueError) as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_ROOT, str(exc), None
        )
    try:
        result = verify_fork_aggregate_chain(
            root, successors, prune_policy, site_policy, policies,
            keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateForkDecisionAggregateError,
            InvalidForkAggregateChainError, TypeError, ValueError) as exc:
        return _fac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_CHAIN, str(exc), None
        )
    return _fac_chain_item_report(
        item_id, PAC_CHAINS_VERIFIED, None, result
    )


def verify_fork_aggregate_chains(items, prune_policy, site_policy,
                                 keyring, moment):
    """Verify a batch of fork aggregate chains and spot successor forks.

    Each item holds exactly a unique non-empty ``id``, its ``root``
    aggregate packet, its ordered ``successors`` packets and its
    per-stage ``policies`` history; ``prune_policy`` is the invariant
    original pruning policy and ``site_policy`` the invariant
    fork-proof site policy shared by every chain, and ``keyring`` and
    ``moment`` keep their single-chain meaning.  The whole batch
    structure -- every key set, element type, policy count and the
    shared materials -- is validated before any chain is verified, so
    only batch-level faults raise (container, element or field type
    faults :class:`TypeError`, a :class:`bool` never posing as an int;
    an empty list, an empty or duplicate id, a wrong policy count or an
    illegal moment :class:`ValueError`).

    Each chain is then verified independently, in strict input order,
    through the exact :func:`verify_fork_aggregate_chain` rules: one
    chain's failure never stops a later chain or changes an earlier
    report.  A root fault reports ``invalid-root``, a successor or
    chain-binding fault ``invalid-chain`` and a credential or signature
    fault ``unauthenticated``, each with a null ``result``; a passing
    chain reports ``verified``.

    The verified chains are grouped by their ``rootDigest`` and only
    successor trajectories under the same aggregate root are compared:
    the same predecessor digest pointing at two distinct successor
    digests is a fork (a mere prefix extension is not).  Every verified
    chain crossing a forking edge is reclassified ``conflicted`` with
    its verified result kept and its ``error`` fixed to
    ``"forked-fork-aggregate-chain"``; invalid and unauthenticated
    chains are never reclassified.

    Returns a fresh dict with the fixed keys ``forks``, ``items`` and
    ``version`` (the integer 1).  ``forks`` is sorted by ``rootDigest``
    then ``predecessorDigest``; each entry carries exactly
    ``rootDigest``, ``predecessorDigest``, ``successors`` (the forking
    successor digests, ascending) and ``ids`` (the ascending ids of the
    chains crossing the edge).  Each item report preserves the input
    order and carries, in this key order, ``error``, ``id``, ``result``
    and ``status``.  No file is read or written and no input is
    modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(site_policy)
    _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    reports: list[dict] = []
    results: list[dict | None] = []
    for item in validated_items:
        report = _verify_fac_chain_item(
            item, prune_policy, site_policy, keyring, verify_moment
        )
        reports.append(report)
        results.append(report[VERDICT_ITEM_RESULT])

    # Fork detection within one root group: one predecessor digest
    # pointing at two distinct successor digests, ignoring chains that
    # did not verify.
    groups: dict[str, dict[str, set[str]]] = {}
    for item, result in zip(validated_items, results):
        if result is None:
            continue
        nodes = _pac_chain_edge_nodes(item)
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    fork_edges: dict[tuple[str, str], list[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                fork_edges[(root_digest, upstream)] = sorted(digests)
    edge_ids: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in fork_edges
    }
    if fork_edges:
        for item, report, result in zip(validated_items, reports, results):
            if result is None:
                continue
            nodes = _pac_chain_edge_nodes(item)
            crosses_fork = False
            for upstream in nodes[:-1]:
                edge = (nodes[0], upstream)
                if edge in fork_edges:
                    edge_ids[edge].add(item[ID])
                    crosses_fork = True
            if crosses_fork:
                report[STATUS] = PAC_CHAINS_CONFLICTED
                report[CHECKPOINT_ITEM_ERROR] = _FAC_CHAIN_ITEM_ERROR

    forks = [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: fork_edges[(root_digest, predecessor)],
            _FORK_IDS: sorted(edge_ids[(root_digest, predecessor)]),
        }
        for root_digest, predecessor in sorted(fork_edges)
    ]
    return {
        CHAINS_FORKS: forks,
        ITEMS: reports,
        VERSION: FORK_AGGREGATE_CHAINS_VERSION,
    }


# -- Stable head anchors for verified, accepted, unforked chains ---------------

def _parse_fac_anchor(raw: object) -> tuple[dict, str]:
    """Validate anchor bytes structurally into ``(payload, signature)``."""
    if not isinstance(raw, bytes):
        raise TypeError("anchor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _fac_chain_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _fac_chain_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_fac_keys
        )
    except json.JSONDecodeError as exc:
        raise _fac_chain_invalid("is not valid JSON") from exc
    if not isinstance(data, dict):
        raise TypeError("anchor must be a JSON object")
    if set(data.keys()) != _FAC_ANCHOR_TOP_KEYS:
        raise _fac_chain_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("anchor signature must be a str")
    if not _prune_is_digest(signature):
        raise _fac_chain_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("anchor payload must be an object")
    if set(payload.keys()) != _FAC_ANCHOR_PAYLOAD_KEYS:
        raise _fac_chain_invalid(
            "payload must contain exactly the keys 'rootDigest', "
            "'headDigest', 'height', 'policyDigest', 'policyVersion', "
            "'moment', 'issuer', 'keyVersion' and 'version'"
        )
    for key in (FAC_ROOT_DIGEST, FAC_HEAD_DIGEST, FAC_POLICY_DIGEST):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _fac_chain_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[FAC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 0:
        raise _fac_chain_invalid("payload height must be non-negative")
    policy_version = payload[FAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _fac_chain_invalid("payload policyVersion must be positive")
    anchor_moment = payload[CP_MOMENT]
    if isinstance(anchor_moment, bool) or not isinstance(anchor_moment, int):
        raise TypeError("payload moment must be an int")
    if anchor_moment < 0:
        raise _fac_chain_invalid("payload moment must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _fac_chain_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _fac_chain_invalid("payload keyVersion must be positive")
    anchor_version = payload[VERSION]
    if isinstance(anchor_version, bool) or not isinstance(
        anchor_version, int
    ):
        raise TypeError("payload version must be an int")
    if anchor_version != FORK_AGGREGATE_CHAIN_VERSION:
        raise _fac_chain_invalid("payload version must be the integer 1")
    if _prune_compact(data) != raw:
        raise _fac_chain_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def seal_fork_aggregate_head(
    items, target, prune_policy, site_policy, keyring, moment, issuer, version
):
    """Seal a stable anchor over one target head within the batch.

    The batch is first run through the exact
    :func:`verify_fork_aggregate_chains` rules.  An anchor is sealed
    only for the ``target`` chain when it is ``verified`` -- never
    conflicted by a fork in this batch, invalid or unauthenticated --
    and its head is ``accepted``; otherwise sealing raises
    :class:`ValueError`.  Other chains' failures never stop the
    target's anchor, though their forks still reclassify it when they
    share an edge.  The anchor binds that chain's root digest, head
    digest and height together with the head decision policy digest,
    the head policy version and the sealing moment, and is signed with
    HMAC-SHA256 under the exact ``issuer``/``version`` key usable at
    ``moment``.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``.  A parameter or public field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty value, an unknown or duplicate target id, an illegal version
    or a wrong policy count raises :class:`ValueError`; a chain fault
    raises the underlying
    :class:`InvalidAggregateForkDecisionAggregateError` or
    :class:`InvalidForkAggregateChainError`; a signing credential fault
    raises :class:`AuthenticationError`.  No file is read or written
    and no input is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    seal_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_fork_aggregate_chains(
        items, prune_policy, site_policy, keyring, seal_moment
    )
    entry_report = report[ITEMS][target_index]
    if entry_report[STATUS] != PAC_CHAINS_VERIFIED:
        raise ValueError(
            "an anchor seals only a verified target with no fork"
        )
    result = entry_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise ValueError("an anchor seals only an accepted head")
    target_item = validated_items[target_index]
    head_packet = (
        target_item[PAC_BATCH_SUCCESSORS][-1]
        if target_item[PAC_BATCH_SUCCESSORS] else target_item[PAC_BATCH_ROOT]
    )
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    if result[FAC_HEAD_DIGEST] != hashlib.sha256(head_packet).hexdigest():
        raise ValueError("the sealed head digest does not match its packet")
    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, seal_moment
    )
    payload = {
        FAC_ROOT_DIGEST: result[FAC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: result[FAC_HEAD_DIGEST],
        FAC_HEIGHT: result[FAC_HEIGHT],
        FAC_POLICY_DIGEST: _pac_policy_digest(head_policy),
        FAC_POLICY_VERSION: result[FAC_POLICY_VERSION],
        CP_MOMENT: seal_moment,
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        VERSION: FORK_AGGREGATE_CHAIN_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def verify_fork_aggregate_head(
    anchor, items, target, prune_policy, site_policy, keyring, moment
):
    """Re-verify a sealed fork aggregate anchor entirely offline.

    The anchor is checked structurally and its HMAC verified against
    the current keyring key bound to its exact issuer and version,
    usable at the verification ``moment``.  The original batch (with
    ``target`` naming the anchored chain) is then re-run through
    :func:`verify_fork_aggregate_chains`; the target must again verify
    with no fork and an accepted head, and its root digest, head
    digest, height and policy version must equal the anchor bindings
    while the bound policy digest must equal the digest of the target's
    head policy.

    Returns a fresh mapping with fixed keys ``rootDigest``,
    ``headDigest``, ``height``, ``policyDigest``, ``policyVersion`` and
    ``anchorDigest`` (the SHA-256 of the anchor bytes).  A non-bytes or
    wrong-type argument raises :class:`TypeError`; an empty value, a
    duplicate or unknown target id, an illegal version or a wrong policy
    count raises :class:`ValueError`; a bad anchor, successor or chain
    binding raises :class:`InvalidForkAggregateChainError`; a malformed
    root raises :class:`InvalidAggregateForkDecisionAggregateError`; a
    signature or credential fault raises :class:`AuthenticationError`.
    No file is read or written and no input is modified.
    """
    if not isinstance(anchor, bytes):
        raise TypeError("anchor must be bytes")
    payload, signature = _parse_fac_anchor(anchor)
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "fork aggregate anchor signature does not match"
        )

    report = verify_fork_aggregate_chains(
        items, prune_policy, site_policy, keyring, verify_moment
    )
    entry_report = report[ITEMS][target_index]
    if entry_report[STATUS] != PAC_CHAINS_VERIFIED:
        raise _fac_chain_invalid(
            "the anchored target no longer verifies without a fork"
        )
    result = entry_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise _fac_chain_invalid("the anchored head is no longer accepted")
    target_item = validated_items[target_index]
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    head_policy_digest = _pac_policy_digest(head_policy)
    if result[FAC_ROOT_DIGEST] != payload[FAC_ROOT_DIGEST]:
        raise _fac_chain_invalid("root digest does not match the anchor")
    if result[FAC_HEAD_DIGEST] != payload[FAC_HEAD_DIGEST]:
        raise _fac_chain_invalid("head digest does not match the anchor")
    if result[FAC_HEIGHT] != payload[FAC_HEIGHT]:
        raise _fac_chain_invalid("height does not match the anchor")
    if result[FAC_POLICY_VERSION] != payload[FAC_POLICY_VERSION]:
        raise _fac_chain_invalid(
            "policy version does not match the anchor"
        )
    if head_policy_digest != payload[FAC_POLICY_DIGEST]:
        raise _fac_chain_invalid("policy digest does not match the anchor")
    return {
        FAC_ROOT_DIGEST: payload[FAC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: payload[FAC_HEAD_DIGEST],
        FAC_HEIGHT: payload[FAC_HEIGHT],
        FAC_POLICY_DIGEST: head_policy_digest,
        FAC_POLICY_VERSION: payload[FAC_POLICY_VERSION],
        FAC_ANCHOR_DIGEST: hashlib.sha256(anchor).hexdigest(),
    }

# -- Signed fork proofs over a fork aggregate chain batch ---------------------

CHAIN_FORK_PROOF_VERSION = 1
CHAIN_FORK_DECISION_VERSION = 1

CF_PROOF_PRUNE_POLICY = "prunePolicy"
CF_PROOF_SITE_POLICY = "sitePolicy"
CF_PROOF_RESULT_KEYS = (
    FORK_PROOF_CHAINS,
    VD_ISSUER,
    KEY_VERSION,
    CP_MOMENT,
    PAFD_PRUNE_POLICY_DIGEST,
    PAFD_SITE_POLICY_DIGEST,
    FORK_PROOF_DIGEST,
    FORK_PROOF_REPORT,
    VERSION,
)

_CF_PROOF_TOP_KEYS = frozenset((TICKET_PAYLOAD, SIGNATURE))
_CF_PROOF_PAYLOAD_KEYS = frozenset((
    FORK_PROOF_CHAINS,
    VD_ISSUER,
    KEY_VERSION,
    CP_MOMENT,
    CF_PROOF_PRUNE_POLICY,
    CF_PROOF_SITE_POLICY,
    FORK_PROOF_REPORT,
    VERSION,
))

_CF_PROOFS_VERSION = 1
_CF_PROOFS_VERIFIED = "verified"
_CF_PROOFS_INVALID = "invalid-proof"
_CF_PROOFS_UNAUTHENTICATED = "unauthenticated"

_CF_DECISION_COMMON = PAFD_COMMON
_CF_DECISION_PROOFS = PAFD_PROOFS
_CF_PROOF_DIGEST = CP_DIGEST
_CF_EDGES = PAFD_EDGES

_CF_STATUS_ACCEPTED = PA_STATUS_ACCEPTED
_CF_STATUS_CONFLICTED = PA_STATUS_CONFLICTED
_CF_STATUS_INSUFFICIENT = PA_STATUS_INSUFFICIENT


class InvalidChainProofError(ValueError):
    """A chain fork proof breaks its binding contract."""


class InvalidChainDecisionError(ValueError):
    """A signed chain fork decision breaks its binding contract."""


def _cf_proof_invalid(message: str) -> InvalidChainProofError:
    return InvalidChainProofError(f"invalid chain fork proof: {message}")


def _cf_decision_invalid(message: str) -> InvalidChainDecisionError:
    return InvalidChainDecisionError(
        f"invalid chain fork decision: {message}"
    )


def _reject_duplicate_cf_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _cf_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _parse_chain_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate chain fork proof bytes into ``(payload, signature, chains)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, count, ordering, reference or
    report-binding fault raises :class:`InvalidChainProofError`.  The
    two policy bindings, the moment and the signature are checked by
    :func:`verify_chain_fork_proof`.
    """

# -- Signed fork proofs over chain fork aggregate chain batches ---------------
#
# These entry points sit one layer above ``sign_chain_fork_proof``: that
# proof packages the ``verify_fork_aggregate_chains`` batch (fork
# aggregate supersession chains), while this layer packages the
# ``verify_chain_fork_aggregate_chains`` batch (chain fork aggregate
# supersession chains), reusing the same proof envelope, the same two
# shared policies (the invariant original prune policy and the fork-proof
# site policy) and the same InvalidChainProofError /
# InvalidChainDecisionError hierarchies.  Adjudication additionally
# takes a separate site authorization policy.

CHAIN_FORK_AGGREGATE_PROOF_VERSION = 1
CHAIN_FORK_AGGREGATE_DECISION_VERSION = 1

_CFA_PROOFS_VERSION = 1
_CFA_PROOFS_VERIFIED = _CF_PROOFS_VERIFIED
_CFA_PROOFS_INVALID = _CF_PROOFS_INVALID
_CFA_PROOFS_UNAUTHENTICATED = _CF_PROOFS_UNAUTHENTICATED

_CFA_AUTHZ_POLICY_DIGEST = "authorizationPolicyDigest"

_CFA_DECISION_PAYLOAD_KEYS = frozenset((
    PAFD_COMMON,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    PAFD_PRUNE_POLICY_DIGEST,
    PAFD_PROOFS,
    _CFA_AUTHZ_POLICY_DIGEST,
    STATUS,
    VERSION,
))


def _cfa_proof_invalid(message: str) -> InvalidChainProofError:
    return InvalidChainProofError(
        f"invalid chain fork aggregate proof: {message}"
    )


def _cfa_decision_invalid(message: str) -> InvalidChainDecisionError:
    return InvalidChainDecisionError(
        f"invalid chain fork aggregate decision: {message}"
    )


def _reject_duplicate_cfa_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _cfa_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _parse_cfa_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate chain fork aggregate proof bytes structurally.

    Returns ``(payload, signature, chains)``.  A non-bytes argument or a
    public field of the wrong type raises :class:`TypeError` (a
    :class:`bool` never poses as an int); every encoding, key-set,
    version, digest, count, ordering, reference or report-binding fault
    raises :class:`InvalidChainProofError`.  The two policy bindings, the
    moment and the signature are checked by the proof verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _cfa_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _cfa_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_cfa_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _cfa_proof_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("proof must be a JSON object")
    if set(data.keys()) != _CF_PROOF_TOP_KEYS:
        raise _cfa_proof_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("proof signature must be a str")
    if not _prune_is_digest(signature):
        raise _cfa_proof_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("proof payload must be an object")
    if set(payload.keys()) != _CF_PROOF_PAYLOAD_KEYS:
        raise _cfa_proof_invalid(
            "payload must contain exactly the keys 'chains', 'issuer', "
            "'keyVersion', 'moment', 'prunePolicy', 'report', 'sitePolicy' "
            "and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _cfa_proof_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _cfa_proof_invalid("payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("payload moment must be an int")
    if moment < 0:
        raise _cfa_proof_invalid("payload moment must be non-negative")
    for field in (CF_PROOF_PRUNE_POLICY, CF_PROOF_SITE_POLICY):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _cfa_proof_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("payload version must be an int")
    if version != CHAIN_FORK_AGGREGATE_PROOF_VERSION:
        raise _cfa_proof_invalid("payload version must be the integer 1")
    chains = _validated_pac_fork_chains(
        payload[FORK_PROOF_CHAINS], invalid=_cfa_proof_invalid
    )
    _validated_pac_fork_report(
        payload[FORK_PROOF_REPORT], chains,
        conflicted_error=_CFCA_CHAIN_ITEM_ERROR,
        invalid=_cfa_proof_invalid,
        report_version=CHAIN_FORK_AGGREGATE_CHAINS_VERSION,
    )

    if _prune_compact(data) != raw:
        raise _cfa_proof_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature, chains


def sign_chain_fork_aggregate_proof(items, prune_policy, site_policy,
                                    keyring, moment, issuer, version):
    """Sign the fork summary of a chain fork aggregate chain batch.

    ``items`` is the same non-empty list of ``{"id", "root",
    "successors", "policies"}`` dicts
    :func:`verify_chain_fork_aggregate_chains` takes; ``prune_policy`` is
    the shared invariant original ``{"batch","sites","threshold"}``
    pruning policy and ``site_policy`` the shared fork-proof site policy,
    ``keyring`` follows the existing rules, ``moment`` is the signing
    time and ``issuer``/``version`` name the signing credentials.  The
    batch first runs through the exact
    :func:`verify_chain_fork_aggregate_chains` rules and the proof is
    issued only when the resulting report records at least one fork (a
    fork-free report raises :class:`ValueError`).  No file is read or
    written and no argument is modified.

    The proof is one canonical compact UTF-8 JSON object -- every object
    key recursively sorted, non-ASCII preserved, no trailing newline or
    any other trailing byte -- carrying exactly ``payload`` and
    ``signature``.  The payload binds exactly ``chains`` (every input
    chain in input order: ``id``, the ``root`` digest, every
    ``successors`` digest and the canonical digest of every versioned
    site policy in the complete ``policies`` history), ``issuer``,
    ``keyVersion``, ``moment``, ``prunePolicy`` (the lowercase hex
    SHA-256 of the canonical compact prune policy encoding), ``report``
    (the complete chain-batch report), ``sitePolicy`` (the SHA-256 of
    the canonical compact fork-proof site policy) and ``version`` (the
    integer 1).  ``signature`` is the lowercase hex HMAC-SHA256 of the
    canonical compact payload bytes under the key the keyring binds to
    the exact issuer and version, with no fallback.

    A parameter or public field type fault raises :class:`TypeError`
    (a :class:`bool` never poses as an int); an empty list, an empty or
    duplicate id, a wrong policy count, an empty issuer, a non-positive
    version, a negative moment, an illegal shared policy or a report
    without a fork raises :class:`ValueError`; and unknown, revoked,
    not-yet-valid or expired credentials raise
    :class:`AuthenticationError`.
    """
    validated_items = _validated_fac_chain_batch(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_chain_fork_aggregate_chains(
        validated_items, prune_policy, site_policy, keyring, sign_moment
    )
    if not report[CHAINS_FORKS]:
        raise ValueError(
            "a chain fork aggregate proof requires at least one fork in "
            "the chain report"
        )
    entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )
    payload = {
        FORK_PROOF_CHAINS: _pac_chain_materials(validated_items),
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        CP_MOMENT: sign_moment,
        CF_PROOF_PRUNE_POLICY: hashlib.sha256(
            _verdict_policy_bytes(validated_prune_policy)
        ).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(report),
        CF_PROOF_SITE_POLICY: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_site_policy)
        ).hexdigest(),
        VERSION: CHAIN_FORK_AGGREGATE_PROOF_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _verify_cfa_fork_proof_core(
    raw: bytes,
    validated_prune_policy: dict,
    validated_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one chain fork aggregate proof against validated materials.

    Shared core of the batch verifier; the caller owns the
    argument-type and shared-material validation.  The returned dict is
    freshly built solely from authenticated proof material.
    """
    payload, signature, chains = _parse_cfa_fork_proof(raw)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[CF_PROOF_PRUNE_POLICY] != expected_prune_digest:
        raise _cfa_proof_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[CF_PROOF_SITE_POLICY] != expected_site_digest:
        raise _cfa_proof_invalid(
            "site policy digest does not match the site policy"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _cfa_proof_invalid(
            "moment must not be later than the verification moment"
        )

    key_entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "chain fork aggregate proof signature does not match"
        )

    return {
        FORK_PROOF_CHAINS: copy.deepcopy(chains),
        VD_ISSUER: payload[VD_ISSUER],
        KEY_VERSION: payload[KEY_VERSION],
        CP_MOMENT: payload[CP_MOMENT],
        PAFD_PRUNE_POLICY_DIGEST: expected_prune_digest,
        PAFD_SITE_POLICY_DIGEST: expected_site_digest,
        FORK_PROOF_DIGEST: hashlib.sha256(raw).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(payload[FORK_PROOF_REPORT]),
        VERSION: CHAIN_FORK_AGGREGATE_PROOF_VERSION,
    }


# -- Offline batch verification of chain fork aggregate proofs ----------------

def _cfa_proofs_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One chain fork aggregate proof batch report, fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_cfa_fork_proof_item(
    item: dict,
    validated_prune_policy: dict,
    validated_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one chain fork aggregate proof in isolation.

    Unknown, revoked, not-yet-valid or expired credentials and a wrong
    signature make the item ``unauthenticated``; every encoding,
    key-set, version, digest, ordering, reference or report-binding
    fault makes it ``invalid-proof``; a passing proof is ``verified``.
    """
    item_id = item[ID]
    try:
        result = _verify_cfa_fork_proof_core(
            item[FORK_PROOF_ITEM_PROOF],
            validated_prune_policy,
            validated_site_policy,
            validated_keyring,
            moment,
        )
    except AuthenticationError as exc:
        return _cfa_proofs_item_report(
            item_id, _CFA_PROOFS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidChainProofError, TypeError) as exc:
        # A TypeError here can only come from a wrong JSON field type
        # *inside* the proof bytes; the public argument types were all
        # validated before the batch ran.
        return _cfa_proofs_item_report(
            item_id, _CFA_PROOFS_INVALID, str(exc), None
        )
    return _cfa_proofs_item_report(
        item_id, _CFA_PROOFS_VERIFIED, None, result
    )


def verify_chain_fork_aggregate_proofs(items, prune_policy, site_policy,
                                       keyring, moment):
    """Verify a whole batch of chain fork aggregate proofs offline.

    ``items`` is a non-empty list; each item is a dict with exactly the
    keys ``id`` (a non-empty str, unique across the batch) and ``proof``
    (the bytes :func:`sign_chain_fork_aggregate_proof` produced).  The
    whole batch structure and the shared prune policy, fork-proof site
    policy, keyring and moment are validated in full before any proof is
    verified: container, element or field type faults raise
    :class:`TypeError` (a :class:`bool` never poses as an int) and an
    empty list, an empty or duplicate id or a wrong item key set raises
    :class:`ValueError` (the shared materials keep their single-entry
    classification).  Only these batch-level faults raise.

    Each proof is then verified independently, in strict input order,
    through the chain fork aggregate proof rules: one proof's failure
    never stops a later proof or alters an earlier report, and a failed
    item always keeps a null result and a definite non-empty error.
    Unknown, revoked, not-yet-valid or expired credentials or a wrong
    signature make the item ``unauthenticated``; an illegal encoding,
    key set, version, digest, count, ordering, reference or report
    binding makes it ``invalid-proof``; a passing proof is ``verified``.

    The top-level result is a fresh dict with the fixed keys ``items``
    and ``version`` (the integer 1); each item report carries, in this
    key order, ``error`` (null exactly when verified), ``id``,
    ``result`` (a fresh independent copy of the single-proof result
    when verified, otherwise null -- the identity of an unauthenticated
    payload never enters a result) and ``status``.  Repeated calls
    return equal but mutually independent results.  No file is read or
    written and no input is modified.
    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    return {
        ITEMS: [
            _verify_cfa_fork_proof_item(
                item, validated_prune_policy, validated_site_policy,
                validated_keyring, verify_moment,
            )
            for item in validated_items
        ],
        VERSION: _CFA_PROOFS_VERSION,
    }


# -- Multi-site threshold adjudication over chain fork aggregate proofs -------

def _adjudicate_cfa_one(
    item: dict,
    prune_policy_digest: str,
    site_policy_digest: str,
    authorization_policy: dict,
    keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify, authorize and authenticate one chain fork aggregate proof.

    The proof is first checked through the exact chain fork aggregate
    proof structural rules, then the signing site and key version are
    authorized exactly against the separate site authorization policy
    with no fallback, and finally the HMAC is checked against the
    current keyring.  Any failure rejects just this row with one fixed
    reason and never affects the other items.
    """
    item_id = item[ID]
    raw_proof = item[FORK_PROOF_ITEM_PROOF]
    proof_digest = hashlib.sha256(raw_proof).hexdigest()

    def structural_invalid() -> dict:
        return _cf_row(
            item_id, proof_digest, None, None, None,
            _PAFD_CONCLUSION_INVALID, _PAFD_REASON_INVALID_PROOF,
        )

    try:
        payload, signature, _chains = _parse_cfa_fork_proof(raw_proof)
    except (TypeError, ValueError):
        return structural_invalid()

    site = payload[VD_ISSUER]
    key_version = payload[KEY_VERSION]
    try:
        edges = _pac_fork_proof_edges(payload)
    except (TypeError, ValueError):
        return structural_invalid()

    def reject(reason: str) -> dict:
        return _cf_row(
            item_id, proof_digest, site, key_version, edges,
            _PAFD_CONCLUSION_INVALID, reason,
        )

    # Both shared policy digests must match and the proof must not be
    # dated after the adjudication moment; a mismatch makes the claimed
    # identity untrustworthy, so the row carries none.  Authorization
    # itself is governed by the separate authorization policy.
    if payload[CF_PROOF_PRUNE_POLICY] != prune_policy_digest:
        return structural_invalid()
    if payload[CF_PROOF_SITE_POLICY] != site_policy_digest:
        return structural_invalid()
    if payload[CP_MOMENT] > moment:
        return structural_invalid()

    allowed_versions = authorization_policy[ADJ_SITES].get(site)
    if allowed_versions is None:
        return reject(REASON_UNAUTHORIZED_SITE)
    if key_version not in allowed_versions:
        return reject(REASON_UNAUTHORIZED_VERSION)

    key_entry = None
    for candidate in keyring.get(site, ()):
        if candidate[VERSION] == key_version:
            key_entry = candidate
            break
    if key_entry is None:
        return reject(REASON_CREDENTIAL_UNAVAILABLE)
    if key_entry[REVOKED]:
        return reject(REASON_REVOKED)
    if moment < key_entry[NOT_BEFORE]:
        return reject(REASON_NOT_YET_VALID)
    if moment > key_entry[NOT_AFTER]:
        return reject(REASON_EXPIRED)

    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        return reject(REASON_BAD_SIGNATURE)

    return _cf_row(
        item_id, proof_digest, site, key_version, edges,
        _PAFD_CONCLUSION_VALID, None,
    )


def adjudicate_chain_fork_aggregate_proofs(items, prune_policy, site_policy,
                                           authorization_policy, keyring,
                                           moment, issuer, version):
    """Adjudicate multi-site chain fork aggregate proofs offline.

    ``items`` is a non-empty list; each item contains exactly a unique
    non-empty ``id`` and ``proof`` bytes produced by
    :func:`sign_chain_fork_aggregate_proof`.  ``prune_policy`` is the
    shared invariant original ``{"batch","sites","threshold"}`` pruning
    policy the proofs were issued against and ``site_policy`` the
    fork-proof site policy their payloads digest; ``authorization_policy``
    additionally carries exactly ``sites`` (a non-empty map of each
    authorized non-empty signing site to its non-empty set of allowed
    positive key versions) and ``threshold`` (a positive integer no
    greater than the site count).  ``keyring`` follows the existing
    rules, ``moment`` is the non-negative adjudication moment and
    ``issuer``/``version`` name the adjudicator credentials.  No file is
    read or written and no input is modified.

    Every proof is first independently re-verified through the chain
    fork aggregate proof rules (a structurally illegal, foreign-policy
    or future-dated proof is ``invalid-proof`` carrying no identity),
    then authorized precisely by the exact payload identity and key
    version against the authorization policy with no fallback
    (``unauthorized-site``, ``unauthorized-version``), then
    authenticated against the current keyring
    (``credential-unavailable``, ``revoked``, ``not-yet-valid``,
    ``expired``, ``bad-signature``); one item's rejection never blocks a
    later item.  For one site, proofs whose complete fork edge set --
    every edge of root digest, forking predecessor digest and the
    ascending set of legal successor digests -- is identical count once
    and every extra proof is ``duplicate``, while two distinct complete
    edge sets from one site are a ``contradiction``.  Distinct sites
    must agree exactly on the complete edge set; any same-site
    contradiction or cross-site difference is ``conflicted`` with a null
    common set and can never be outvoted by a majority.  A unique edge
    set backed by at least the threshold of distinct sites is
    ``accepted``; the same unique set short of the threshold is
    ``insufficient`` yet still binds that common set; with no valid vote
    at all the common set is null.

    The packet is one canonical compact UTF-8 JSON object with
    recursively sorted keys, non-ASCII preserved and no trailing byte,
    carrying exactly ``payload`` and ``signature``; the payload binds
    exactly the two policy digests -- ``prunePolicyDigest`` and
    ``authorizationPolicyDigest`` (the SHA-256 of the canonical site
    authorization policy) -- together with ``common`` (the
    stable-sorted common fork edge set, or null), ``issuer``, ``items``
    (the rows stably sorted by site then id, each carrying
    ``conclusion``, the authenticated ``edges`` or null, ``id``,
    ``issuer``, ``keyVersion``, the proof ``digest`` and ``reason``),
    ``keyVersion``, ``proofs`` (each input proof's SHA-256 in the
    original input order), ``status`` and ``version`` (the integer 1).
    The fork-proof site policy is already digested inside every signed
    proof and so is not repeated in the decision.  The signature is the
    lowercase hex HMAC-SHA256 of the canonical payload bytes under the
    exact adjudicator issuer/version key.

    A parameter, container or public-field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an empty
    list, an empty or duplicate id, or an illegal policy, threshold,
    moment, issuer or version raises :class:`ValueError`; unknown,
    revoked, not-yet-valid or expired adjudicator credentials raise
    :class:`AuthenticationError`.
    """

    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()

    # The proof summaries keep the original input order, independent of
    # the stably sorted conclusion rows.
    proof_digests = [
        hashlib.sha256(item[FORK_PROOF_ITEM_PROOF]).hexdigest()
        for item in validated_items
    ]
    rows = [
        _adjudicate_cfa_one(
            item, prune_policy_digest, site_policy_digest,
            validated_authorization_policy, validated_keyring, moment,
        )
        for item in validated_items
    ]

    contradicted, votes = _tally_pac_fork_rows(rows)

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _CF_STATUS_CONFLICTED
        common = None
    elif len(edge_sets) == 1:
        common = _sorted_pac_fork_edge_objects(next(iter(edge_sets)))
        if len(votes) >= validated_authorization_policy[ADJ_THRESHOLD]:
            status = _CF_STATUS_ACCEPTED
        else:
            status = _CF_STATUS_INSUFFICIENT
    else:
        status = _CF_STATUS_INSUFFICIENT
        common = None

    rows.sort(
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        )
    )

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, moment
    )
    payload = {
        _CF_DECISION_COMMON: common,
        VD_ISSUER: issuer,
        ITEMS: [copy.deepcopy(row) for row in rows],
        KEY_VERSION: version,
        PAFD_PRUNE_POLICY_DIGEST: prune_policy_digest,
        _CF_DECISION_PROOFS: proof_digests,
        _CFA_AUTHZ_POLICY_DIGEST: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_authorization_policy)
        ).hexdigest(),
        STATUS: status,
        VERSION: CHAIN_FORK_AGGREGATE_DECISION_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _parse_cfa_decision(raw: object) -> tuple[dict, str]:
    """Validate chain fork aggregate decision bytes structurally.

    A non-bytes argument or a field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest or value-format fault raises
    :class:`InvalidChainDecisionError`.  The policy, tally and
    credential bindings are checked by the decision verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("decision must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _cfa_decision_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _cfa_decision_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text,
            object_pairs_hook=lambda pairs: _reject_duplicate_pafd_keys(
                pairs, _cfa_decision_invalid
            ),
        )
    except json.JSONDecodeError as exc:
        raise _cfa_decision_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("decision must be a JSON object")
    if set(data.keys()) != _PAFD_DECISION_TOP_KEYS:
        raise _cfa_decision_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("decision signature must be a str")
    if not _prune_is_digest(signature):
        raise _cfa_decision_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("decision payload must be an object")
    if set(payload.keys()) != _CFA_DECISION_PAYLOAD_KEYS:
        raise _cfa_decision_invalid(
            "payload must contain exactly the keys 'common', 'issuer', "
            "'items', 'keyVersion', 'prunePolicyDigest', 'proofs', "
            "'authorizationPolicyDigest', 'status' and 'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _cfa_decision_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _cfa_decision_invalid("payload keyVersion must be positive")
    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PAFD_STATUSES:
        raise _cfa_decision_invalid("payload status is not a known status")
    for field in (PAFD_PRUNE_POLICY_DIGEST, _CFA_AUTHZ_POLICY_DIGEST):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _cfa_decision_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )

    proofs = payload[PAFD_PROOFS]
    if not isinstance(proofs, list):
        raise TypeError("payload proofs must be a list")
    if not proofs:
        raise _cfa_decision_invalid("payload proofs must be non-empty")
    for position, digest in enumerate(proofs):
        if not isinstance(digest, str):
            raise TypeError(f"payload proof {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _cfa_decision_invalid(
                f"payload proof {position} digest must be 64 lowercase hex "
                "characters"
            )

    raw_rows = payload[ITEMS]
    if not isinstance(raw_rows, list):
        raise TypeError("payload items must be a list")
    if not raw_rows:
        raise _cfa_decision_invalid("payload items must be non-empty")
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        where = f"payload item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be an object")
        if set(row.keys()) != _PAFD_ROW_KEYS:
            raise _cfa_decision_invalid(
                f"{where} must contain exactly the keys 'conclusion', "
                "'edges', 'id', 'keyVersion', 'digest', 'reason' and "
                "'site'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{where} id must be a str")
        if row_id == "":
            raise _cfa_decision_invalid(f"{where} id must be non-empty")
        if row_id in seen_ids:
            raise _cfa_decision_invalid(f"{where} repeats an id")
        seen_ids.add(row_id)
        digest = row[_CF_PROOF_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _cfa_decision_invalid(
                f"{where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None:
            if not isinstance(site, str):
                raise TypeError(f"{where} site must be a str or null")
            if site == "":
                raise _cfa_decision_invalid(f"{where} site must be non-empty")
        row_key_version = row[KEY_VERSION]
        if isinstance(row_key_version, bool) or not isinstance(
            row_key_version, int
        ):
            if row_key_version is not None:
                raise TypeError(f"{where} keyVersion must be an int or null")
        elif row_key_version <= 0:
            raise _cfa_decision_invalid(f"{where} keyVersion must be positive")
        if (site is None) != (row_key_version is None):
            raise _cfa_decision_invalid(
                f"{where} site and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{where} conclusion must be a str")
        if conclusion not in _PAFD_CONCLUSIONS:
            raise _cfa_decision_invalid(f"{where} conclusion is not known")
        reason = row[ADJ_REASON]
        if conclusion == _PAFD_CONCLUSION_VALID:
            if reason is not None:
                raise _cfa_decision_invalid(
                    f"{where} reason must be null for a valid item"
                )
        else:
            if not isinstance(reason, str):
                raise TypeError(f"{where} reason must be a str")
            if reason not in _PAFD_REASONS:
                raise _cfa_decision_invalid(f"{where} reason is not known")
        if conclusion == _PAFD_CONCLUSION_INVALID:
            if reason not in _PAFD_INVALID_REASONS:
                raise _cfa_decision_invalid(
                    f"{where} reason does not match an invalid item"
                )
        elif conclusion != _PAFD_CONCLUSION_VALID:
            if reason != conclusion:
                raise _cfa_decision_invalid(
                    f"{where} reason must match its conclusion"
                )

        raw_edges = row[PAFD_EDGES]
        if raw_edges is not None:
            if not isinstance(raw_edges, list):
                raise TypeError(f"{where} edges must be a list or null")
            if not raw_edges:
                raise _cfa_decision_invalid(
                    f"{where} edges must be non-empty for an authenticated "
                    "proof"
                )
            row_edges = [
                _validated_pafd_edge(value, where, _cfa_decision_invalid)
                for value in raw_edges
            ]
            triples = _pac_fork_edge_triples(row_edges)
            if len(set(triples)) != len(triples):
                raise _cfa_decision_invalid(f"{where} edges must be unique")
            if list(triples) != sorted(triples):
                raise _cfa_decision_invalid(
                    f"{where} edges must be sorted ascending"
                )
        identity_expected = reason != _PAFD_REASON_INVALID_PROOF
        if identity_expected:
            if site is None or raw_edges is None:
                raise _cfa_decision_invalid(
                    f"{where} an authenticated proof must carry its site and "
                    "fork edges"
                )
        else:
            if site is not None or raw_edges is not None:
                raise _cfa_decision_invalid(
                    f"{where} an invalid-proof item must carry no site or "
                    "fork edges"
                )

    common = payload[PAFD_COMMON]
    if common is not None:
        if not isinstance(common, list):
            raise TypeError("payload common must be a list or null")
        if not common:
            raise _cfa_decision_invalid(
                "a bound common edge set must be non-empty"
            )
        common_edges = [
            _validated_pafd_edge(value, "payload common",
                                 _cfa_decision_invalid)
            for value in common
        ]
        common_triples = _pac_fork_edge_triples(common_edges)
        if len(set(common_triples)) != len(common_triples) or list(
            common_triples
        ) != sorted(common_triples):
            raise _cfa_decision_invalid(
                "payload common edges must be unique and sorted ascending"
            )

    decision_version = payload[VERSION]
    if isinstance(decision_version, bool) or not isinstance(
        decision_version, int
    ):
        raise TypeError("payload version must be an int")
    if decision_version != CHAIN_FORK_AGGREGATE_DECISION_VERSION:
        raise _cfa_decision_invalid("payload version must be the integer 1")

    if _prune_compact(data) != raw:
        raise _cfa_decision_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def verify_chain_fork_aggregate_decision(decision, prune_policy,
                                         authorization_policy, keyring,
                                         moment):
    """Re-verify a signed chain fork aggregate decision entirely offline.

    Only the decision bytes, the expected shared ``prune_policy``, the
    expected site ``authorization_policy``, the current ``keyring`` and
    the verification ``moment`` are consulted -- no file is read or
    written and no argument is modified.  The decision binds the two
    policy digests (the prune policy and the site authorization
    policy); the fork-proof site policy is already digested inside
    every signed proof the decision rows name.  Verification validates
    the canonical encoding and every key set, recomputes both policy
    digests, re-tallies the bound per-proof rows purely from the signed
    payload (the stable site/id row ordering, the original-order proof
    digest vector as a multiset independent of the row order, the
    same-site duplicate/contradiction markings, the cross-site complete
    edge-set agreement, the authorization threshold outcome and the
    claimed common set), and checks the HMAC-SHA256 against the key the
    current keyring binds to the payload's exact issuer and version,
    usable at the verification moment, so a later revocation or expiry
    rejects the decision with no fallback.

    On success a fresh depth-independent mapping is returned with the
    fixed keys ``common``, ``proofDigest`` (the SHA-256 of the decision
    bytes), ``issuer``, ``items``, ``keyVersion``,
    ``prunePolicyDigest``, ``proofs``, ``authorizationPolicyDigest``,
    ``status`` and ``version`` (the integer 1); repeated calls return
    equal but mutually independent objects.  A non-bytes decision or a
    wrong public field type raises :class:`TypeError` (a :class:`bool`
    never poses as an int); an empty value, a duplicate id, a wrong key
    set or an illegal policy, threshold, moment, site or version raises
    :class:`ValueError`; an illegal decision structure, ordering, tally
    or binding raises :class:`InvalidChainDecisionError` (a
    :class:`ValueError` subclass, distinct from
    :class:`InvalidChainProofError`); unknown, revoked, not-yet-valid or
    expired credentials or a wrong signature raise
    :class:`AuthenticationError`.
    """
    if not isinstance(decision, bytes):
        raise TypeError("decision must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    return _verify_cfa_decision_core(
        decision, validated_prune_policy, validated_authorization_policy,
        validated_keyring, verify_moment,
    )


def _verify_cfa_decision_core(
    decision: bytes,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one chain fork aggregate decision against validated materials.

    This is the shared core of
    :func:`verify_chain_fork_aggregate_decision` and the batch
    :func:`verify_chain_fork_aggregate_decisions`; the caller owns the
    argument-type and shared-material validation.  The returned dict is
    freshly built solely from authenticated decision material.
    """
    payload, signature = _parse_cfa_decision(decision)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[PAFD_PRUNE_POLICY_DIGEST] != expected_prune_digest:
        raise _cfa_decision_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_authorization_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_CFA_AUTHZ_POLICY_DIGEST] != expected_authorization_digest:
        raise _cfa_decision_invalid(
            "authorization policy digest does not match the authorization "
            "policy"
        )

    # The proof digest vector stays in the original input order, so only
    # its multiset must agree with the stably sorted rows.
    status = _reconcile_pafd(
        payload, validated_authorization_policy[ADJ_THRESHOLD],
        invalid=_cfa_decision_invalid, positional_proofs=False,
    )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "chain fork aggregate decision signature does not match"
        )

    return {
        key: copy.deepcopy(value)
        for key, value in (
            (PAFD_COMMON, payload[PAFD_COMMON]),
            (FORK_PROOF_DIGEST, hashlib.sha256(decision).hexdigest()),
            (VD_ISSUER, payload[VD_ISSUER]),
            (ITEMS, payload[ITEMS]),
            (KEY_VERSION, payload[KEY_VERSION]),
            (PAFD_PRUNE_POLICY_DIGEST, expected_prune_digest),
            (PAFD_PROOFS, payload[PAFD_PROOFS]),
            (_CFA_AUTHZ_POLICY_DIGEST, expected_authorization_digest),
            (STATUS, status),
            (VERSION, CHAIN_FORK_AGGREGATE_DECISION_VERSION),
        )
    }


# -- Batch verification and cross-site aggregation of chain fork aggregate ----
# -- decisions -----------------------------------------------------------------
#
# This layer mirrors the chain fork decision aggregate (``cfda``) layer but
# its source packets are :func:`adjudicate_chain_fork_aggregate_proofs`
# decisions: their proof summary vector keeps the original input order (the
# positional term-by-term binding of the ``cfda`` layer does not apply) and
# their second policy digest is the site authorization policy.  The wire
# field names follow the ``cfda`` layer; only the packet taxonomy, the
# non-positional proof bindings and the error classes differ.

